    "pm_stats_label": "P150 MAX в цифрах",
    "pm_spray_t": "Опрыскивание",
    "pm_spray_p": "Интеллектуальные центробежные форсунки и два гибких насоса точно дозируют раствор, а мощный поток от четырёх роторов загоняет капли в густую крону. С дополнительным комплектом на 4 форсунки расход достигает 46 л/мин — рекомендуется для садов и виноградников.",
    "pm_f_flow": "Расход, два насоса",
    "pm_f_flow4": "С комплектом на 4 форсунки",
    "pm_f_drop": "Размер капли",
    "pm_f_swath": "Ширина опрыскивания",
    "pm_spread_t": "Разбрасывание гранул",
    "pm_spread_p": "Вертикальный качающийся разбрасыватель с прямым приводом распределяет материал равномерно даже при ветре. Шнековые дозаторы трёх размеров принимают гранулы до 10 мм — удобрения, семена, корм; бункер заполняется с обеих сторон.",
    "pm_f_rate": "Макс. производительность*",
    "pm_f_spw": "Эффективная ширина",
    "pm_f_gran": "Макс. размер гранулы",
    "pm_cargo_t": "Перевозка грузов",
    "pm_cargo_p": "Доставка удобрений, урожая, кассет с рассадой и саженцев в труднодоступные места. Надёжный замок груза с автоматическим сбросом, маршруты A/B, свои траектории для холмистой местности и взвешивание в полёте.",
    "pm_f_slingspeed": "Макс. скорость с грузом",
    "pm_map_t": "Картографирование",
    "pm_map_p": "Встроено, без дополнительного модуля: в автономном полёте снимает фото высокого разрешения, сшивает их в карту поля и выдаёт сразу после посадки. ИИ сам распознаёт препятствия, для холмов есть 3D-модель, а карты-предписания позволяют вносить препараты с переменной нормой.",
    "pm_f_3d": "Модель для холмистой местности",
    "pm_f_vra": "Переменная норма по карте",
    "pm_flight_t": "Полёт и безопасность",
    "pm_flight_p": "4D-радар видит опоры, провода, поливные установки и другие препятствия днём и ночью. Следование рельефу без предварительной карты: дрон строит 3D-карту в полёте. Широкоугольная FPV-камера отмечает препятствия в AR, а при опасности дрон автоматически зависает.",
    "pm_f_radar": "Дальность радара",
    "pm_f_cpu": "Вычислительная мощность против SuperX 5 Pro",
    "pm_power_t": "Питание и зарядка",
    "pm_power_p": "Аккумулятор 1050 Вт·ч до 1500 циклов (или 12 месяцев). Одно зарядное CM13600S заряжает с 30% до 95% примерно за 12 минут, параллельный комплект — за 7. Башня туманного охлаждения работает 6–8 часов на одном баке, а генератор GC4000+ делает вас независимыми в поле. Режим одной батареи: 50 л раствора или 40 кг гранул.",
    "pm_f_wh": "Ёмкость аккумулятора",
    "pm_f_cycles": "циклов",
    "pm_f_charge": "Зарядка 30→95%, параллельно",
    "pm_f_kw": "Мощность зарядного",
    "pm_build_t": "Конструкция и управление",
    "pm_build_p": "IPX6K: дрон можно мыть водой. 63-дюймовые пропеллеры, складные лучи и модульная конструкция для перевозки. В приложении XAG One: маршрут по форме поля, до 10 полей за миссию, два дрона одновременно и автовозврат, когда заканчивается раствор или заряд. Пульт SRC 5: яркий 7-дюймовый экран, 8 часов работы. Для сантиметровой точности — мобильная станция XRTK 7.",
    "pm_f_ip": "Класс защиты",
    "pm_f_prop": "Пропеллеры",
    "pm_f_fields": "полей за миссию",
    "pm_f_link": "Видеосвязь (открытое поле)",
